function setup_limit() {
    local limit=$1
    ulimit -n $limit
}

function run_python_process() {
    local script=$1
    python3 -c "$script"
}

function run_bash_process() {
    local script=$1
    bash -c "$script"
}

function cleanup() {
    local pid=$1
    kill -9 $pid 2>/dev/null
}

function main() {
    local temp_dir=$(mktemp -d)
    local python_script="import os; os.close(3); os.close(4); os.close(5);"
    local bash_script="ulimit -n 10; for i in {6..15}; do echo 'Opening FD $i'; exec $i>/dev/null; done;"

    # Run first Python process with FD limit
    setup_limit 10
    run_python_process "$python_script"

    # Run second Bash process without FD limit
    local bash_pid=$(run_bash_process "$bash_script" & echo $!)
    wait $bash_pid

    # Cleanup
    cleanup $bash_pid
    rm -rf $temp_dir
}

