#!/bin/bash

# Base side: Recursive wrapper with array parameter passing

# Function to simulate the core logic
core_logic() {
    local fd=$1
    local dup_fd

    # Create a file and get its FD
    exec {fd}>/dev/null

    # Duplicate the FD
    exec {dup_fd}<>${fd}

    # Close the original FD
    exec {fd}>&-

    # Print the FDs
    echo "Original FD: ${fd}, Duplicated FD: ${dup_fd}"

    # Return the duplicated FD
    echo ${dup_fd}
}

# Wrapper function to handle recursion and array parameter passing
wrapper() {
    local params=("$@")
    local count=${params[0]}
    local fd=${params[1]}
    local dup_fd

    # Base case: if count is 0, return
    if [ ${count} -le 0 ]; then
        return
    fi

    # Call the core logic and get the duplicated FD
    dup_fd=$(core_logic ${fd})

    # Print the current state
    echo "Iteration: $((count)), Original FD: ${fd}, Duplicated FD: ${dup_fd}"

    # Recur with the updated parameters
    wrapper $((count - 1)) ${dup_fd}
}

# Main entry point
main() {
    local count=5
    local initial_fd=3

    # Start the wrapper with initial parameters
    wrapper ${count} ${initial_fd}
}

# Run the main function
main

