#!/bin/bash

# Определение функции с циклом накопления FD, но не вызывай её
accumulate_fd() {
    local count=$1
    local fd_list=()
    for ((i=0; i<count; i++)); do
        fd_list+=("$i")
    done
    echo "${fd_list[@]}"
}

# Wrapper рекурсивно передаёт массив параметров без изменения элементов, отдельно уменьшая счётчик два
wrapper() {
    local params=("$@")
    local count=${#params[@]}
    if (( count > 0 )); then
        echo "Processing ${params[0]}"
        wrapper "${params[@]:1}"
    fi
}

# Точка входа
main() {
    local initial_count=5
    local fd_list=($(accumulate_fd $initial_count))
    wrapper "${fd_list[@]}"
}

