import os

def manage_fds():
    fds = []
    try:
        while True:
            fd = os.open("/dev/null", os.O_RDONLY)
            fds.append(fd)
            if len(fds) > 2:
                os.close(fds.pop(0))
    finally:
        for fd in fds:
            os.close(fd)

