#!/bin/bash

# Function to create and manage socketpair
create_socketpair() {
    local sp=()
    socketpair -p "${sp[@]}"
    local fd0=${sp[0]}
    local fd1=${sp[1]}

    # Show lifetime of both halves
    echo "Created socketpair: fd0=$fd0, fd1=$fd1"

    # Keep both socket objects open
    while true; do
        sleep 1
    done
}

# Define the EXIT trap
cleanup() {
    echo "Cleanup: EXIT trap triggered"
    # No resources to close in this scenario
}

# Register the EXIT trap
trap cleanup EXIT

# Start the socketpair creation loop
create_socketpair

